d = 'MAKBNBMCGKMBDBKKMBPBBBMMENMBBEKE'

def rm_noise(s):
    # places = [1,2,3,6,8,9,10,13]
    # places = [0, 1, 2, 5, 7, 8, 9, 12]
    places = [1, 2, 4, 8, 9, 13, 14, 15]
    a = wrap(s, 16)  # делим строку на блоки по 32 символа
    r = ''
    for w in a:
        for i in range(len(w)):  # проходим по всем символам блока
            if i not in places:  # добавляем только не шум
                r += w[i]
    return r

